def transform2(g):
    g=[row[:] for row in g]
    h,w=len(g),len(g[0])
    cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]==3]
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    frame={(r,c) for r,c in cells if r in(r0,r1) or c in(c0,c1)}
    seed=[p for p in cells if p not in frame][0]
    for r in range(r0+1,r1):
        for c in range(c0+1,c1):
            d=max(abs(r-seed[0]),abs(c-seed[1]))
            g[r][c]= 3 if d==0 else (4 if d%2==1 else 2)
    return g
